'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isFloat64Array = require( '@stdlib/assert/is-float64array' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var Float64Array = require( './../lib' );


// FUNCTIONS //

/**
* Comparison function.
*
* @private
* @param {number} a - first value for comparison
* @param {number} b - second value for comparison
* @returns {number} comparison result
*/
function compareFcn( a, b ) {
	if ( a < b ) {
		return -1;
	}
	if ( a > b ) {
		return 1;
	}
	return 0;
}


// MAIN //

bench( format( '%s:toSorted', pkg ), function benchmark( b ) {
	var out;
	var arr;
	var i;

	arr = new Float64Array( [ 1, 2, 3, 4, 5, 6 ] );

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = arr.toSorted( compareFcn );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isFloat64Array( out ) ) {
		b.fail( 'should return a Float64Array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
